      "proposed_laureates": [
        "Andrea J. Liu",
        "Sidney R. Nagel"
      ],
      "assessment": {
        "nobel_worthiness": "Work on jamming and rigidity exposed organizing principles for disordered materials and connected phenomena across granular matter, glasses, and soft condensed matter.",
        "attribution": "Liu and Nagel were central in framing and developing the jamming perspective.",
        "maturity": "The field has developed substantially, though a single settled theory of jamming across systems remains elusive.",
        "uncertainties": [
          "The breadth of the phenomenon makes it hard to define a single discovery and its boundaries."
        ]
      }
    },
    {
